#include <ATen/DeviceGuard.h>
#include <ATen/Functions.h>
#include <c10/xpu/XPUStream.h>
#include <torch/library.h>

#include <sycl/sycl.hpp>

namespace {

template <int M>
void launch_small_m(sycl::queue& queue, const sycl::half* x,
                    const int32_t* packed_weight, const sycl::half* scales,
                    sycl::half* out, int64_t k, int64_t n,
                    int64_t group_size) {
  constexpr int local_size = 256;
  const int64_t global_size = ((n + local_size - 1) / local_size) * local_size;
  queue.parallel_for(
      sycl::nd_range<1>(global_size, local_size),
      [=](sycl::nd_item<1> item) {
        const int64_t column = item.get_global_linear_id();
        if (column >= n) return;
        float accumulators[M] = {};
        const int64_t packed_k = k / 8;
        for (int64_t packed_index = 0; packed_index < packed_k;
             ++packed_index) {
          const uint32_t word = static_cast<uint32_t>(
              packed_weight[column * packed_k + packed_index]);
#pragma unroll
          for (int nibble = 0; nibble < 8; ++nibble) {
            const int64_t inner = packed_index * 8 + nibble;
            const int quantized = static_cast<int>((word >> (nibble * 4)) & 15) - 8;
            const float weight = static_cast<float>(quantized) *
                                 static_cast<float>(scales[(inner / group_size) * n + column]);
#pragma unroll
            for (int row = 0; row < M; ++row) {
              accumulators[row] += static_cast<float>(x[row * k + inner]) * weight;
            }
          }
        }
#pragma unroll
        for (int row = 0; row < M; ++row) {
          out[row * n + column] = static_cast<sycl::half>(accumulators[row]);
        }
      });
}

at::Tensor gptq_small_m(const at::Tensor& x, const at::Tensor& packed_weight,
                        const at::Tensor& scales, const at::Tensor& zero_point,
                        int64_t group_size) {
  const at::DeviceGuard guard(x.device());
  TORCH_CHECK(x.is_xpu() && packed_weight.is_xpu() && scales.is_xpu() &&
                  zero_point.is_xpu(),
              "all tensors must be on XPU");
  TORCH_CHECK(x.scalar_type() == at::kHalf && scales.scalar_type() == at::kHalf,
              "x and scales must be FP16");
  TORCH_CHECK(packed_weight.scalar_type() == at::kInt,
              "packed_weight must be int32");
  TORCH_CHECK(zero_point.scalar_type() == at::kChar && zero_point.numel() == 1,
              "only a scalar int8 symmetric zero point is supported");
  TORCH_CHECK(x.dim() == 2 && x.is_contiguous() && x.size(0) >= 1 &&
                  x.size(0) <= 5,
              "x must be contiguous [M,K] with 1 <= M <= 5");
  const int64_t m = x.size(0), k = x.size(1), n = packed_weight.size(1);
  TORCH_CHECK(group_size == 128 && k % 128 == 0,
              "only group_size=128 is supported");
  TORCH_CHECK(packed_weight.dim() == 2 && packed_weight.size(0) == k / 8 &&
                  packed_weight.stride(0) == 1 &&
                  packed_weight.stride(1) == k / 8,
              "packed_weight must be the GPTQ [K/8,N] transposed view");
  TORCH_CHECK(scales.dim() == 2 && scales.size(0) == k / group_size &&
                  scales.size(1) == n && scales.is_contiguous(),
              "scales must be contiguous [K/group_size,N]");
  auto out = at::empty({m, n}, x.options());
  auto& queue = c10::xpu::getCurrentXPUStream().queue();
  const auto* x_ptr = reinterpret_cast<const sycl::half*>(x.data_ptr<at::Half>());
  const auto* w_ptr = packed_weight.data_ptr<int32_t>();
  const auto* s_ptr = reinterpret_cast<const sycl::half*>(scales.data_ptr<at::Half>());
  auto* out_ptr = reinterpret_cast<sycl::half*>(out.data_ptr<at::Half>());
  if (m == 1) launch_small_m<1>(queue,x_ptr,w_ptr,s_ptr,out_ptr,k,n,group_size);
  else if (m == 2) launch_small_m<2>(queue,x_ptr,w_ptr,s_ptr,out_ptr,k,n,group_size);
  else if (m == 3) launch_small_m<3>(queue,x_ptr,w_ptr,s_ptr,out_ptr,k,n,group_size);
  else if (m == 4) launch_small_m<4>(queue,x_ptr,w_ptr,s_ptr,out_ptr,k,n,group_size);
  else launch_small_m<5>(queue,x_ptr,w_ptr,s_ptr,out_ptr,k,n,group_size);
  return out;
}

}  // namespace

TORCH_LIBRARY_FRAGMENT(b70_ops, m) {
  m.def("gptq_small_m(Tensor x, Tensor packed_weight, Tensor scales, "
        "Tensor zero_point, int group_size) -> Tensor");
}
TORCH_LIBRARY_IMPL(b70_ops, XPU, m) {
  m.impl("gptq_small_m", &gptq_small_m);
}

#include "chunk_prefill.hpp"
#include <c10/xpu/XPUStream.h>
#include <torch/library.h>
using namespace cute;

namespace {
template <int Q, int SG> struct Policy {
  using ShapeQK = Shape<Int<Q>, _32, _32>;
  using ShapePV = Shape<Int<Q>, _32, _32>;
  using ShapeOut = Shape<Int<Q>, _256>;
  using SubgroupLayoutQK = Layout<Shape<Int<SG>, _1, _1>>;
};
template <int Q, int SG>
void launch(sycl::queue& queue, const chunk_prefill_args_t& args) {
  using P = Policy<Q, SG>;
  FMHAConfig<typename P::ShapeQK, typename P::ShapePV, typename P::ShapeOut,
             typename P::SubgroupLayoutQK, void, 2, true, true, false, false,
             false, half_t, float_e4m3_t, float_e4m3_t,
             half_t>::kernel_dispatch(queue, args);
}

void check_inputs(const at::Tensor& q, const at::Tensor& k,
                  const at::Tensor& v, const at::Tensor& block_table,
                  const at::Tensor& cu_seqlens_q,
                  const at::Tensor& seqused_k, const at::Tensor& k_scale,
                  const at::Tensor& v_scale, const at::Tensor& out,
                  int64_t max_seqlen_k, int64_t variant) {
  TORCH_CHECK(q.is_xpu() && k.is_xpu() && v.is_xpu() && out.is_xpu(),
              "q, k, v and out must be XPU tensors");
  TORCH_CHECK(block_table.is_xpu() && cu_seqlens_q.is_xpu() &&
                  seqused_k.is_xpu() && k_scale.is_xpu() && v_scale.is_xpu(),
              "metadata and scales must be XPU tensors");
  TORCH_CHECK(q.scalar_type() == at::kHalf && out.scalar_type() == at::kHalf,
              "q and out must be FP16");
  TORCH_CHECK(k.scalar_type() == at::ScalarType::Float8_e4m3fn &&
                  v.scalar_type() == k.scalar_type(), "k and v must be E4M3FN");
  TORCH_CHECK(q.dim() == 3 && q.size(1) == 24 && q.size(2) == 256,
              "q must have shape [M,24,256]");
  TORCH_CHECK(k.dim() == 4 && k.size(1) == 1664 && k.size(2) == 4 &&
                  k.size(3) == 256 && v.sizes() == k.sizes() &&
                  v.strides() == k.strides(),
              "k/v must share shape [pages,1664,4,256] and strides");
  TORCH_CHECK(out.sizes() == q.sizes() && out.strides() == q.strides(),
              "out must have q's shape and strides");
  TORCH_CHECK(q.is_contiguous() && out.is_contiguous(),
              "q and out must be contiguous");
  TORCH_CHECK(block_table.dim() == 2 && block_table.size(0) == 1 &&
                  block_table.scalar_type() == at::kInt && block_table.is_contiguous(),
              "block_table must be contiguous int32 with batch size one");
  TORCH_CHECK(cu_seqlens_q.numel() == 2 && cu_seqlens_q.scalar_type() == at::kInt &&
                  cu_seqlens_q.is_contiguous(),
              "cu_seqlens_q must contain two contiguous int32 values");
  TORCH_CHECK(seqused_k.numel() == 1 && seqused_k.scalar_type() == at::kInt &&
                  seqused_k.is_contiguous(),
              "seqused_k must contain one contiguous int32 value");
  TORCH_CHECK(k_scale.scalar_type() == at::kFloat && v_scale.scalar_type() == at::kFloat &&
                  k_scale.numel() == 1 && v_scale.numel() == 1,
              "k/v scales must be scalar FP32 tensors");
  TORCH_CHECK(max_seqlen_k > 0, "max_seqlen_k must be positive");
  TORCH_CHECK(variant >= 0 && variant <= 2, "variant must be 0, 1 or 2");
  TORCH_CHECK(!out.is_alias_of(q) && !out.is_alias_of(k) && !out.is_alias_of(v),
              "out must not alias q, k or v");
}

at::Tensor& q128_forward_out(
    const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
    const at::Tensor& block_table, const at::Tensor& cu_seqlens_q,
    const at::Tensor& seqused_k, const at::Tensor& k_scale,
    const at::Tensor& v_scale, at::Tensor& out, int64_t max_seqlen_k,
    int64_t variant) {
  check_inputs(q, k, v, block_table, cu_seqlens_q, seqused_k, k_scale,
               v_scale, out, max_seqlen_k, variant);
  chunk_prefill_args_t a{};
  a.query=q.data_ptr(); a.key=k.data_ptr(); a.value=v.data_ptr(); a.out=out.data_ptr();
  a.block_table=block_table.data_ptr(); a.cu_seqlens_q=cu_seqlens_q.data_ptr();
  a.cu_seqlens_k=seqused_k.data_ptr(); a.max_queries=q.size(0); a.max_keys=max_seqlen_k;
  a.total_seqlen_q=q.size(0); a.total_seqlen_k=get_paged_kv_cache_effective_total_seqlen(k);
  a.k_scale=k_scale.data_ptr(); a.v_scale=v_scale.data_ptr(); a.sm_scale=0.0625f;
  a.batch_size=1; a.num_heads_q=24; a.num_heads_k=4; a.head_size=256;
  a.max_blocks_per_seq=block_table.size(1); a.block_size=1664;
  a.is_varlen=true; a.is_paged=true; a.is_causal=true;
  a.q_stride_seq=q.stride(0); a.q_stride_heads=q.stride(1);
  a.o_stride_seq=out.stride(0); a.o_stride_heads=out.stride(1);
  a.k_stride_seq=k.stride(1); a.k_stride_heads=k.stride(2);
  a.v_stride_seq=v.stride(1); a.v_stride_heads=v.stride(2);
  a.page_stride_elements=get_paged_kv_cache_page_stride_elements(k);
  auto& queue=c10::xpu::getCurrentXPUStream().queue();
  if(variant==0) launch<256,32>(queue,a);
  else if(variant==1) launch<128,16>(queue,a);
  else launch<64,8>(queue,a);
  return out;
}

at::Tensor q128_forward(const at::Tensor& q, const at::Tensor& k,
                        const at::Tensor& v, const at::Tensor& block_table,
                        const at::Tensor& cu_seqlens_q, const at::Tensor& seqused_k,
                        const at::Tensor& k_scale, const at::Tensor& v_scale,
                        int64_t max_seqlen_k, int64_t variant) {
  auto out=at::empty_like(q);
  q128_forward_out(q,k,v,block_table,cu_seqlens_q,seqused_k,k_scale,v_scale,
                   out,max_seqlen_k,variant);
  return out;
}
}

TORCH_LIBRARY(b70_ops,m) {
  m.def("q128_forward(Tensor q, Tensor k, Tensor v, Tensor block_table, Tensor cu_seqlens_q, Tensor seqused_k, Tensor k_scale, Tensor v_scale, int max_seqlen_k, int variant) -> Tensor");
  m.def("q128_forward_out(Tensor q, Tensor k, Tensor v, Tensor block_table, Tensor cu_seqlens_q, Tensor seqused_k, Tensor k_scale, Tensor v_scale, Tensor(a!) out, int max_seqlen_k, int variant) -> Tensor(a!)");
}
TORCH_LIBRARY_IMPL(b70_ops,XPU,m) {
  m.impl("q128_forward",&q128_forward);
  m.impl("q128_forward_out",&q128_forward_out);
}

#define B70_VERIFY_MASK 1
#include "paged_decode.hpp"

#include <c10/xpu/XPUStream.h>
#include <torch/library.h>

using namespace cute;

namespace {

using VerifyPolicy = decode_policy_qpacked_head<_16, _256, _64>;
using VerifyPolicyQ8 = decode_policy_qpacked_head<_8, _256, _64>;

void check_inputs(const at::Tensor& q, const at::Tensor& k,
                  const at::Tensor& v, const at::Tensor& block_table,
                  const at::Tensor& cu_seqlens_q,
                  const at::Tensor& seqused_k, const at::Tensor& k_scale,
                  const at::Tensor& v_scale, const at::Tensor& out,
                  const at::Tensor& temp_out, const at::Tensor& exp_sums,
                  const at::Tensor& max_logits, int64_t max_seqlen_k,
                  int64_t num_splits, int64_t q_tile) {
  TORCH_CHECK(q.is_xpu() && k.is_xpu() && v.is_xpu() && out.is_xpu(),
              "q, k, v and out must be XPU tensors");
  TORCH_CHECK(q.scalar_type() == at::kHalf && out.scalar_type() == at::kHalf,
              "q and out must be FP16");
  TORCH_CHECK(k.scalar_type() == at::ScalarType::Float8_e4m3fn &&
                  v.scalar_type() == k.scalar_type(),
              "k and v must be E4M3FN");
  TORCH_CHECK(q.dim() == 3 && q.size(0) == 1 && q.size(2) == 256 &&
                  q.size(1) >= 48 && q.size(1) <= 120 && q.size(1) % 24 == 0,
              "packed q must have shape [1,48|72|96|120,256]");
  TORCH_CHECK(k.dim() == 4 && k.size(1) == 1664 && k.size(2) == 4 &&
                  k.size(3) == 256 && v.sizes() == k.sizes() &&
                  v.strides() == k.strides(),
              "k/v must share production shape and strides");
  TORCH_CHECK(q.is_contiguous() && out.is_contiguous() &&
                  out.sizes() == q.sizes(),
              "q/out must be contiguous and have equal shapes");
  TORCH_CHECK(block_table.dim() == 2 && block_table.size(0) == 1 &&
                  block_table.scalar_type() == at::kInt &&
                  block_table.is_contiguous(),
              "block_table must be one contiguous int32 row");
  TORCH_CHECK(cu_seqlens_q.numel() == 2 &&
                  cu_seqlens_q.scalar_type() == at::kInt &&
                  seqused_k.numel() == 1 &&
                  seqused_k.scalar_type() == at::kInt,
              "invalid sequence metadata");
  TORCH_CHECK(k_scale.scalar_type() == at::kFloat &&
                  v_scale.scalar_type() == at::kFloat &&
                  k_scale.numel() == 1 && v_scale.numel() == 1,
              "k/v scales must be scalar FP32 tensors");
  TORCH_CHECK(num_splits >= 1 && num_splits <= 32,
              "num_splits must be in [1,32]");
  TORCH_CHECK(q_tile == 8 || q_tile == 16, "q_tile must be 8 or 16");
  TORCH_CHECK(temp_out.numel() == q.numel() * num_splits &&
                  temp_out.scalar_type() == at::kHalf,
              "invalid split output scratch");
  TORCH_CHECK(exp_sums.numel() == q.size(1) * num_splits &&
                  max_logits.numel() == exp_sums.numel() &&
                  exp_sums.scalar_type() == at::kFloat &&
                  max_logits.scalar_type() == at::kFloat,
              "invalid reduction scratch");
  TORCH_CHECK(max_seqlen_k > 0, "max_seqlen_k must be positive");
}

at::Tensor& shared_kv_verify_out(
    const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
    const at::Tensor& block_table, const at::Tensor& cu_seqlens_q,
    const at::Tensor& seqused_k, const at::Tensor& k_scale,
    const at::Tensor& v_scale, at::Tensor& out, at::Tensor& temp_out,
    at::Tensor& exp_sums, at::Tensor& max_logits, int64_t max_seqlen_k,
    int64_t num_splits, int64_t q_tile) {
  check_inputs(q, k, v, block_table, cu_seqlens_q, seqused_k, k_scale,
               v_scale, out, temp_out, exp_sums, max_logits, max_seqlen_k,
               num_splits, q_tile);
  paged_decode_args_t args{};
  args.query = q.data_ptr();
  args.key = k.data_ptr();
  args.value = v.data_ptr();
  args.out = out.data_ptr();
  args.tem_out = num_splits == 1 ? out.data_ptr() : temp_out.data_ptr();
  args.exp_sums = exp_sums.data_ptr();
  args.max_logits = max_logits.data_ptr();
  args.block_table = block_table.data_ptr();
  args.cu_seqlens_q = cu_seqlens_q.data_ptr();
  args.cu_seqlens_k = seqused_k.data_ptr();
  args.max_queries = 1;
  args.max_keys = max_seqlen_k;
  args.total_seqlen_q = 1;
  args.total_seqlen_k = get_paged_kv_cache_effective_total_seqlen(k);
  args.k_scale = k_scale.data_ptr();
  args.v_scale = v_scale.data_ptr();
  args.sm_scale = 0.0625f;
  args.batch_size = 1;
  args.num_heads_q = q.size(1);
  args.num_heads_k = 4;
  args.head_size = 256;
  args.v_head_size = 256;
  args.max_blocks_per_seq = block_table.size(1);
  args.block_size = 1664;
  args.is_varlen = true;
  args.is_paged = true;
  args.is_causal = true;
  args.num_kv_splits = num_splits;
  args.q_stride_seq = q.stride(0);
  args.q_stride_heads = q.stride(1);
  args.k_stride_page = k.stride(0);
  args.k_stride_seq = k.stride(1);
  args.k_stride_heads = k.stride(2);
  args.v_stride_page = v.stride(0);
  args.v_stride_seq = v.stride(1);
  args.v_stride_heads = v.stride(2);
  args.page_stride_elements = get_paged_kv_cache_page_stride_elements(k);
  auto& queue = c10::xpu::getCurrentXPUStream().queue();
  if (q_tile == 8) {
    PagedDecodeConfig<typename VerifyPolicyQ8::ShapeQK,
                      typename VerifyPolicyQ8::ShapePV,
                      typename VerifyPolicyQ8::ShapeOut,
                      typename VerifyPolicyQ8::SubgroupLayoutQK, void, 1,
                      true, false, false, half_t, float_e4m3_t, float_e4m3_t,
                      half_t>::kernel_dispatch(queue, args);
  } else {
    PagedDecodeConfig<typename VerifyPolicy::ShapeQK,
                      typename VerifyPolicy::ShapePV,
                      typename VerifyPolicy::ShapeOut,
                      typename VerifyPolicy::SubgroupLayoutQK, void, 1, true,
                      false, false, half_t, float_e4m3_t, float_e4m3_t,
                      half_t>::kernel_dispatch(queue, args);
  }
  return out;
}

}  // namespace

TORCH_LIBRARY_FRAGMENT(b70_ops, m) {
  m.def("shared_kv_verify_out(Tensor q, Tensor k, Tensor v, Tensor block_table, Tensor cu_seqlens_q, Tensor seqused_k, Tensor k_scale, Tensor v_scale, Tensor(a!) out, Tensor(b!) temp_out, Tensor(c!) exp_sums, Tensor(d!) max_logits, int max_seqlen_k, int num_splits, int q_tile) -> Tensor(a!)");
}

TORCH_LIBRARY_IMPL(b70_ops, XPU, m) {
  m.impl("shared_kv_verify_out", &shared_kv_verify_out);
}

