    s=torch.cat([read(prefix+f'in_proj_{part}.scales') for part in ['qkv','z']],dim=1).contiguous()
    ba=torch.cat([read(prefix+f'in_proj_{part}.weight') for part in ['b','a']],dim=0).contiguous()
    for part in ['qkv','z']:
