#!/usr/bin/env python3
"""Publish a content-free aggregate of the short vLLM 0.30 A/B screen."""

from __future__ import annotations

import argparse
import glob
import json
from pathlib import Path
import statistics


ARMS = ("01-candidate", "02-control", "03-control", "04-candidate")
METRICS = (
    "native_prefill_compute_tokens_per_s",
    "native_weighted_decode_tokens_per_s",
    "fully_overlapped_aggregate_decode_tokens_per_s",
    "batch_wall_s",
)


def read_one(pattern: str) -> dict:
    paths = glob.glob(pattern)
    if len(paths) != 1:
        raise RuntimeError(f"expected one file for {pattern}, found {len(paths)}")
    return json.loads(Path(paths[0]).read_text())


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run-dir", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    root = args.run_dir.resolve()
    plan = json.loads((root / "plan.json").read_text())
    mtp_enabled = plan.get("mtp_enabled", True)
    metrics = METRICS + (("speculative_acceptance",) if mtp_enabled else ())
    cases: dict[str, list[dict]] = {}
    runtimes = []
    versions = {}
    output_hashes = {}
    dispatch = {}
    for arm in ARMS:
        result = read_one(str(root / arm / "benchmark" / "run-*" / "results.json"))
        rows = result["cases"]
        if len(rows) != 4:
            raise RuntimeError(f"{arm}: expected four measured waves")
        for row in rows:
            if not (
                row["all_outputs_nonempty"]
                and row["all_completion_counts_exact"]
                and row["all_finish_reasons_length"]
                and row["preemptions"] == 0
                and row["prompt_tokens_cached"] == 0
            ):
                raise RuntimeError(f"{arm}: failed request validation")
        log = (root / arm / "server.log").read_text()
        dispatch[arm] = {
            "q128": "B70_Q128_DISPATCH" in log,
            "m04": "B70_M04_SHARED_KV_DISPATCH" in log,
        }
        if mtp_enabled and not dispatch[arm]["q128"]:
            raise RuntimeError(f"{arm}: Q128 dispatch missing")
        if mtp_enabled != dispatch[arm]["m04"]:
            raise RuntimeError(f"{arm}: unexpected M04 dispatch state")
        if not mtp_enabled and any(
            row["speculative_draft_tokens"] != 0 or row["speculative_accepted_tokens"] != 0
            for row in rows
        ):
            raise RuntimeError(f"{arm}: speculative tokens observed with MTP disabled")
        cases[arm] = rows
        runtime = json.loads((root / arm / "runtime.json").read_text())
        expected_image = plan["candidate_image" if "candidate" in arm else "control_image"]
        if runtime["image"] != expected_image:
            raise RuntimeError(f"{arm}: image differs from plan")
        runtimes.append(runtime)
        versions[arm] = (root / arm / "versions.txt").read_text().splitlines()
        expected_version = "0.30.0+xpu" if "candidate" in arm else "0.29.0+xpu"
        if versions[arm] != [expected_version, "0.1.14.1"]:
            raise RuntimeError(f"{arm}: unexpected vLLM or XPU kernel version")
        output_hashes[arm] = {
            (path.parent.name, index): request["output_sha256"]
            for path in (root / arm / "benchmark").glob("run-*/v030-*-r*/summary.json")
            for index, request in enumerate(json.loads(path.read_text())["requests"])
        }
        if len(output_hashes[arm]) != 10:
            raise RuntimeError(f"{arm}: expected ten measured output hashes")
    if any(
        item["args"] != runtimes[0]["args"]
        or item["environment"] != runtimes[0]["environment"]
        for item in runtimes[1:]
    ):
        raise RuntimeError("server args or extra environment differ between arms")
    if any(("--speculative-config" in item["args"]) != mtp_enabled for item in runtimes):
        raise RuntimeError("speculative configuration differs from plan")

    prompt_hashes: dict[str, list[str]] = {}
    for arm in ARMS:
        for request_path in (root / arm / "benchmark").glob("run-*/v030-*-r*/request-*.json"):
            key = "/".join(request_path.parts[-2:])
            prompt_hashes.setdefault(key, []).append(
                json.loads(request_path.read_text())["prompt_sha256"]
            )
    if len(prompt_hashes) != 10 or any(
        len(hashes) != len(ARMS) or len(set(hashes)) != 1
        for hashes in prompt_hashes.values()
    ):
        raise RuntimeError("prompt hashes differ or requests are missing")
    if any(set(hashes) != set(output_hashes[ARMS[0]]) for hashes in output_hashes.values()):
        raise RuntimeError("output hash keys differ between arms")

    scenarios: dict[str, dict] = {}
    for scenario in ("v030-4k-c1", "v030-4k-c4"):
        scenario_out: dict[str, dict] = {}
        for version in ("candidate", "control"):
            selected = [
                row for arm, rows in cases.items() if version in arm
                for row in rows if row["scenario"]["name"] == scenario
            ]
            if len(selected) != 4:
                raise RuntimeError(f"{scenario}/{version}: expected four values")
            scenario_out[version] = {
                key: {
                    "mean": statistics.mean(row[key] for row in selected),
                    "min": min(row[key] for row in selected),
                    "max": max(row[key] for row in selected),
                    "values": [row[key] for row in selected],
                }
                for key in metrics
            }
        scenario_out["candidate_vs_control_pct"] = {
            key: 100 * (
                scenario_out["candidate"][key]["mean"]
                / scenario_out["control"][key]["mean"] - 1
            )
            for key in metrics
        }
        scenarios[scenario] = scenario_out
    output = {
        "run_id": root.name,
        "plan": plan,
        "validation": {
            "measured_waves": 16,
            "request_payloads_with_matching_prompt_hashes": len(prompt_hashes),
            "server_args_and_extra_environment_equal": True,
            "custom_dispatch_by_arm": dispatch,
            "all_outputs_nonempty": True,
            "all_output_lengths_exact": True,
            "all_finish_reasons_length": True,
            "all_prefix_cache_hits_zero": True,
            "all_preemptions_zero": True,
            "vllm_and_xpu_kernel_versions": versions,
            "output_hash_matches_between_control_repeats": sum(
                output_hashes["02-control"][key] == output_hashes["03-control"][key]
                for key in output_hashes["02-control"]
            ),
            "measured_requests_per_arm": len(output_hashes[ARMS[0]]),
        },
        "scenarios": scenarios,
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(output, indent=2) + "\n")
    print(args.output)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Freeze four revision-pinned German Wikipedia excerpts for a local benchmark."""

from __future__ import annotations

import argparse
import hashlib
from html.parser import HTMLParser
import json
from pathlib import Path
import re
from urllib.parse import urlencode
from urllib.request import Request, urlopen


ARTICLES = (
    ("Marie Curie", 270535757),
    ("Apollo 11", 268725520),
    ("Photosynthese", 268891481),
    ("Berlin", 270716683),
)
USER_AGENT = "B70WikipediaBenchmark/0.1 (https://github.com/Danmoreng/intel-b70-qwen38-vllm)"
MODEL = "Qwen3.8-27B"
TARGET_TOKENS = 4096
INSTRUCTION = (
    "Fasse den folgenden Auszug aus einem Wikipedia-Artikel auf Deutsch "
    "sachlich zusammen. Schreibe etwa 250 bis 300 Wörter in zusammenhängenden "
    "Absätzen. Nenne die wichtigsten Fakten und Zusammenhänge, bleibe beim "
    "gegebenen Text und füge keine Informationen von außerhalb hinzu."
)


class Paragraphs(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.depth = 0
        self.skip = 0
        self.buffer: list[str] = []
        self.parts: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag == "p":
            self.depth += 1
        elif self.depth and tag in ("sup", "style", "script"):
            self.skip += 1

    def handle_endtag(self, tag: str) -> None:
        if tag in ("sup", "style", "script") and self.skip:
            self.skip -= 1
        elif tag == "p" and self.depth:
            self.depth -= 1
            if not self.depth:
                text = re.sub(r"\s+", " ", "".join(self.buffer)).strip()
                self.buffer = []
                if text:
                    self.parts.append(text)

    def handle_data(self, data: str) -> None:
        if self.depth and not self.skip:
            self.buffer.append(data)


def digest(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


def fetch_article(oldid: int) -> str:
    url = "https://de.wikipedia.org/w/api.php?" + urlencode(
        {"action": "parse", "oldid": oldid, "prop": "text", "format": "json", "formatversion": "2"}
    )
    with urlopen(Request(url, headers={"User-Agent": USER_AGENT}), timeout=30) as response:
        parsed = json.load(response)["parse"]
    if int(parsed["revid"]) != oldid:
        raise RuntimeError(f"revision mismatch: requested {oldid}, received {parsed['revid']}")
    collector = Paragraphs()
    collector.feed(parsed["text"])
    return "\n\n".join(collector.parts)


def token_count(base: str, prompt: str) -> int:
    request = Request(
        base + "/tokenize",
        data=json.dumps({"model": MODEL, "prompt": prompt}).encode(),
        headers={"Content-Type": "application/json"},
    )
    with urlopen(request, timeout=60) as response:
        return int(json.load(response)["count"])


def make_prompt(base: str, title: str, article: str) -> tuple[str, int, str]:
    prefix = f"Wikipedia-Artikel: {title}\n\n"
    suffix = f"\n\nAufgabe: {INSTRUCTION}\n\nZusammenfassung:\n"

    def prompt_at(length: int) -> str:
        return prefix + article[:length] + suffix

    low, high = 0, len(article)
    while low < high:
        mid = (low + high + 1) // 2
        if token_count(base, prompt_at(mid)) <= TARGET_TOKENS:
            low = mid
        else:
            high = mid - 1
    if low == len(article):
        raise RuntimeError(f"article {title!r} is shorter than {TARGET_TOKENS} prompt tokens")
    cut = low
    # Prefer a complete sentence close to the token target.
    period = article.rfind(". ", max(0, cut - 650), cut)
    if period != -1:
        cut = period + 1
    else:
        space = article.rfind(" ", max(0, cut - 100), cut)
        if space != -1:
            cut = space
    excerpt = article[:cut].rstrip()
    prompt = prefix + excerpt + suffix
    count = token_count(base, prompt)
    if not 3900 <= count <= TARGET_TOKENS:
        raise RuntimeError(f"{title}: expected about 4K tokens, got {count}")
    return prompt, count, excerpt


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--base", default="http://127.0.0.1:8081")
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    rows = []
    for title, oldid in ARTICLES:
        article = fetch_article(oldid)
        prompt, count, excerpt = make_prompt(args.base, title, article)
        row = {
            "title": title,
            "revision_id": oldid,
            "revision_url": f"https://de.wikipedia.org/w/index.php?oldid={oldid}",
            "article_sha256": digest(article),
            "excerpt_sha256": digest(excerpt),
            "prompt_sha256": digest(prompt),
            "prompt_tokens": count,
            "prompt": prompt,
        }
        rows.append(row)
        print(f"{title}: revision {oldid}, {count} prompt tokens, {len(excerpt)} chars", flush=True)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(rows, ensure_ascii=False, indent=2) + "\n")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Validate and aggregate the four-arm seeded Wikipedia MTP benchmark."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
import statistics


ARMS = ("01-candidate", "02-control", "03-control", "04-candidate")
METRICS = (
    "native_decode_tokens_per_s",
    "native_prefill_compute_tokens_per_s",
    "fully_overlapped_aggregate_decode_tokens_per_s",
    "batch_wall_s",
    "speculative_acceptance",
    "completion_tokens",
)


def distribution(values: list[float]) -> dict:
    return {
        "mean": statistics.mean(values),
        "min": min(values),
        "max": max(values),
        "values": values,
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run-dir", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    root = args.run_dir.resolve()
    plan = json.loads((root / "plan.json").read_text())
    articles = json.loads((root / "prompts.json").read_text())
    if [a["prompt_sha256"] for a in articles] != [a["prompt_sha256"] for a in plan["articles"]]:
        raise RuntimeError("frozen prompts differ from plan")
    cases = {}
    runtimes = []
    versions = {}
    dispatch = {}
    for arm in ARMS:
        rows = json.loads((root / arm / "benchmark" / "results.json").read_text())["cases"]
        if len(rows) != 10 or sum(len(row["requests"]) for row in rows) != 22:
            raise RuntimeError(f"{arm}: expected ten waves and 22 requests")
        if [row["concurrency"] for row in rows] != [1] * 4 + [2] * 2 + [3] * 2 + [4] * 2:
            raise RuntimeError(f"{arm}: scenario order changed")
        for row in rows:
            if (
                row["prompt_tokens_cached"] != 0
                or row["preemptions"] != 0
                or row["speculative_draft_tokens"] <= 0
                or row["speculative_accepted_tokens"] <= 0
                or row["finished_requests"] != row["concurrency"]
                or row["native_decode_tokens_per_s"] is None
                or row["fully_overlapped_aggregate_decode_tokens_per_s"] is None
            ):
                raise RuntimeError(f"{arm}/{row['label']}: invalid wave")
            for request in row["requests"]:
                if (
                    request["output_chars"] <= 0
                    or request["reasoning_chars"] != 0
                    or not 128 <= request["usage"]["completion_tokens"] <= plan["sampling"]["max_tokens"]
                    or request["finish_reason"] not in ("stop", "length")
                ):
                    raise RuntimeError(f"{arm}/{row['label']}: invalid response")
        cases[arm] = rows
        runtime = json.loads((root / arm / "runtime.json").read_text())
        expected_image = plan["candidate_image" if "candidate" in arm else "control_image"]
        if runtime["image"] != expected_image or "--speculative-config" not in runtime["args"]:
            raise RuntimeError(f"{arm}: unexpected image or MTP configuration")
        runtimes.append(runtime)
        versions[arm] = (root / arm / "versions.txt").read_text().splitlines()
        expected_version = "0.30.0+xpu" if "candidate" in arm else "0.29.0+xpu"
        if versions[arm] != [expected_version, "0.1.14.1"]:
            raise RuntimeError(f"{arm}: unexpected versions")
        log = (root / arm / "server.log").read_text()
        dispatch[arm] = {
            "q128": "B70_Q128_DISPATCH" in log,
            "m04": "B70_M04_SHARED_KV_DISPATCH" in log,
            "v2_runner": "Using V2 Model Runner" in log,
        }
    if any(
        runtime["args"] != runtimes[0]["args"]
        or runtime["environment"] != runtimes[0]["environment"]
        for runtime in runtimes[1:]
    ):
        raise RuntimeError("serving arguments or extra environment differ")

    request_keys = {}
    output_hashes = {}
    for arm, rows in cases.items():
        request_keys[arm] = [
            (row["label"], position, request["prompt_sha256"], request["seed"])
            for row in rows
            for position, request in enumerate(row["requests"])
        ]
        output_hashes[arm] = [request["output_sha256"] for row in rows for request in row["requests"]]
    if any(request_keys[arm] != request_keys[ARMS[0]] for arm in ARMS[1:]):
        raise RuntimeError("prompts, seeds or request order differ between arms")

    scenarios = {}
    for concurrency in (1, 2, 3, 4):
        result = {}
        for version in ("candidate", "control"):
            selected = [
                row for arm, rows in cases.items() if version in arm
                for row in rows if row["concurrency"] == concurrency
            ]
            expected = 8 if concurrency == 1 else 4
            if len(selected) != expected:
                raise RuntimeError(f"C{concurrency}/{version}: expected {expected} waves")
            result[version] = {metric: distribution([row[metric] for row in selected]) for metric in METRICS}
            drafted = sum(row["speculative_draft_tokens"] for row in selected)
            accepted = sum(row["speculative_accepted_tokens"] for row in selected)
            result[version]["weighted_speculative_acceptance"] = accepted / drafted
            result[version]["total_drafted_tokens"] = drafted
            result[version]["total_accepted_tokens"] = accepted
        result["candidate_vs_control_pct"] = {
            metric: 100 * (result["candidate"][metric]["mean"] / result["control"][metric]["mean"] - 1)
            for metric in METRICS
        }
        result["paired_aggregate_decode_change_pct"] = [
            100 * (
                candidate["fully_overlapped_aggregate_decode_tokens_per_s"]
                / control["fully_overlapped_aggregate_decode_tokens_per_s"] - 1
            )
            for candidate_arm, control_arm in (
                ("01-candidate", "02-control"),
                ("04-candidate", "03-control"),
            )
            for candidate, control in zip(
                [row for row in cases[candidate_arm] if row["concurrency"] == concurrency],
                [row for row in cases[control_arm] if row["concurrency"] == concurrency],
            )
        ]
        scenarios[f"c{concurrency}"] = result

    c1_by_article = {}
    for article in articles:
        title = article["title"]
        c1_by_article[title] = {}
        for version in ("candidate", "control"):
            selected = [
                (wave, row) for arm, rows in cases.items() if version in arm
                for wave in rows if wave["concurrency"] == 1
                for row in wave["requests"] if row["title"] == title
            ]
            if len(selected) != 2:
                raise RuntimeError(f"C1 article coverage changed: {title}/{version}")
            c1_by_article[title][version] = {
                "mean_completion_tokens": statistics.mean(row["usage"]["completion_tokens"] for _, row in selected),
                "mean_native_decode_tokens_per_s": statistics.mean(wave["native_decode_tokens_per_s"] for wave, _ in selected),
                "mean_speculative_acceptance": statistics.mean(wave["speculative_acceptance"] for wave, _ in selected),
                "output_hashes_identical_between_repeats": selected[0][1]["output_sha256"] == selected[1][1]["output_sha256"],
            }

    summary = {
        "run_id": root.name,
        "plan": plan,
        "validation": {
            "measured_waves": 40,
            "measured_requests": 88,
            "matching_prompt_hashes_and_seeds_across_arms": True,
            "matching_server_args_and_extra_environment": True,
            "no_prefix_cache_hits_or_preemptions": True,
            "all_outputs_nonempty_without_reasoning": True,
            "versions": versions,
            "dispatch": dispatch,
            "matching_output_hashes_between_control_repeats": sum(
                left == right for left, right in zip(output_hashes["02-control"], output_hashes["03-control"])
            ),
            "matching_output_hashes_between_candidate_repeats": sum(
                left == right for left, right in zip(output_hashes["01-candidate"], output_hashes["04-candidate"])
            ),
            "requests_per_arm": 22,
        },
        "scenarios": scenarios,
        "c1_by_article": c1_by_article,
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(summary, ensure_ascii=False, indent=2) + "\n")
    print(args.output)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Compare fixed-seed MTP answers with and without prefix caching."""

import argparse
import hashlib
import json
from pathlib import Path
import urllib.request


BASE = "http://127.0.0.1:8081"
INDICES = (17, 211, 399, 577, 799)


def code(index):
    return hashlib.sha256(f"B70-EAGLE-20260923-{index}".encode()).hexdigest()[:12].upper()


def metric(name):
    with urllib.request.urlopen(BASE + "/metrics", timeout=15) as response:
        lines = response.read().decode().splitlines()
    values = [float(line.split()[-1]) for line in lines
              if line.startswith(name + "{") or line.startswith(name + " ")]
    if not values:
        raise RuntimeError(f"missing metric {name}")
    return sum(values)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--mode", choices=("on", "off"), required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    document = "EAGLE/Mamba cache-state check. Answer with the exact code only.\n" + "\n".join(
        f"Record {index:04d}: code {code(index)}; value {index * 17 + 3}."
        for index in range(800)
    )
    cases = []
    for index in INDICES:
        body = {
            "model": "Qwen3.8-27B",
            "messages": [
                {"role": "system", "content": document},
                {"role": "user", "content": f"Return only the code for record {index:04d}."},
            ],
            "max_tokens": 32,
            "temperature": 0,
            "seed": 38,
            "chat_template_kwargs": {"enable_thinking": False},
        }
        before = {key: metric(name) for key, name in {
            "hits": "vllm:prefix_cache_hits_total",
            "drafted": "vllm:spec_decode_num_draft_tokens_total",
            "accepted": "vllm:spec_decode_num_accepted_tokens_total",
            "preemptions": "vllm:num_preemptions_total",
        }.items()}
        request = urllib.request.Request(
            BASE + "/v1/chat/completions", data=json.dumps(body).encode(),
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(request, timeout=120) as response:
            answer = json.load(response)
        after = {key: metric(name) for key, name in {
            "hits": "vllm:prefix_cache_hits_total",
            "drafted": "vllm:spec_decode_num_draft_tokens_total",
            "accepted": "vllm:spec_decode_num_accepted_tokens_total",
            "preemptions": "vllm:num_preemptions_total",
        }.items()}
        content = answer["choices"][0]["message"].get("content") or ""
        row = {
            "record": index, "expected": code(index), "answer": content.strip(),
            "prompt_tokens": answer["usage"]["prompt_tokens"],
            "completion_tokens": answer["usage"]["completion_tokens"],
            "metric_delta": {key: after[key] - before[key] for key in before},
        }
        cases.append(row)
        print(json.dumps(row), flush=True)
    result = {
        "mode": args.mode,
        "document_sha256": hashlib.sha256(document.encode()).hexdigest(),
        "cases": cases,
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(result, indent=2) + "\n")
    if any(row["answer"] != row["expected"] or
           row["metric_delta"]["preemptions"] != 0 or
           row["metric_delta"]["drafted"] <= 0 for row in cases):
        raise RuntimeError("incorrect answer, preemption, or no MTP")
    if args.mode == "on" and any(row["metric_delta"]["hits"] <= 0
                                 for row in cases[1:]):
        raise RuntimeError("cache-on run lacked warm prefix hits")
    if args.mode == "off" and any(row["metric_delta"]["hits"] != 0
                                  for row in cases):
        raise RuntimeError("cache-off run unexpectedly had prefix hits")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Check whether the GDN output reshapes dispatch an XPU copy kernel."""

import argparse
import json
import statistics
from pathlib import Path

import torch
from torch.profiler import ProfilerActivity, profile
from vllm.config import VllmConfig, set_current_vllm_config
from vllm.model_executor.layers.layernorm import RMSNormGated


def event_time(fn):
    start = torch.xpu.Event(enable_timing=True)
    end = torch.xpu.Event(enable_timing=True)
    start.record()
    fn()
    end.record()
    end.synchronize()
    return start.elapsed_time(end)


def trace(fn, path):
    for _ in range(5):
        fn()
    torch.xpu.synchronize()
    with profile(activities=[ProfilerActivity.CPU, ProfilerActivity.XPU]) as prof:
        for _ in range(5):
            fn()
        torch.xpu.synchronize()
    prof.export_chrome_trace(str(path))
    raw = json.loads(path.read_text())
    events = raw["traceEvents"]
    kernels = [row for row in events if row.get("cat") == "kernel"]
    copies = [row for row in kernels if any(word in row.get("name", "").lower()
              for word in ("copy", "reshape", "contiguous"))]
    return {
        "kernel_count": len(kernels),
        "kernel_names": sorted(set(row["name"] for row in kernels)),
        "copy_like_kernels": [{"name": row["name"], "duration_us": row.get("dur")}
                              for row in copies],
        "trace_file": str(path),
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    torch.manual_seed(38)
    tokens, heads, dim, hidden = 4, 48, 128, 5120
    core = torch.randn((tokens, heads, dim), device="xpu", dtype=torch.float16)
    gate = torch.randn_like(core)
    with set_current_vllm_config(VllmConfig()):
        norm = RMSNormGated(
            dim, eps=1e-6, group_size=None, norm_before_gate=True,
            activation="silu", device=torch.device("xpu"), dtype=torch.float16,
        )
    projection = torch.nn.Linear(heads * dim, hidden, bias=False,
                                 device="xpu", dtype=torch.float16)

    def current():
        shape = gate.shape
        x = norm(core.reshape(-1, dim), gate.reshape(-1, dim))
        x = x.reshape(shape).flatten(-2)
        return projection(x)

    def proposed():
        return projection(norm(core, gate).flatten(-2))

    a = current()
    b = proposed()
    torch.xpu.synchronize()
    if not torch.allclose(a, b, rtol=0.01, atol=0.002):
        raise RuntimeError("output differs")
    rows = {}
    for mode in ("eager", "compiled"):
        if mode == "compiled":
            try:
                functions = {
                    "current": torch.compile(current, fullgraph=True),
                    "proposed": torch.compile(proposed, fullgraph=True),
                }
                for fn in functions.values():
                    fn()
            except Exception as error:
                rows[mode] = {"error": repr(error)}
                continue
        else:
            functions = {"current": current, "proposed": proposed}
        for fn in functions.values():
            for _ in range(5):
                fn()
        samples = {name: [] for name in functions}
        for i in range(16):
            for name in (("current", "proposed") if i % 2 == 0 else
                         ("proposed", "current")):
                samples[name].append(event_time(functions[name]))
        traces = {}
        for name, fn in functions.items():
            traces[name] = trace(fn, args.output.with_name(
                args.output.stem + f"-{mode}-{name}.trace.json"
            ))
        rows[mode] = {
            "samples_ms": samples,
            "median_ms": {name: statistics.median(values)
                          for name, values in samples.items()},
            "traces": traces,
        }
        print(json.dumps({"mode": mode, "median_ms": rows[mode]["median_ms"],
                          "copy_like_counts": {name: len(value["copy_like_kernels"])
                                               for name, value in traces.items()}}), flush=True)
    result = {
        "scope": "synthetic GDN output region with production dimensions and dense stand-in projection",
        "shape": {"tokens": tokens, "heads": heads, "head_dim": dim,
                  "hidden_size": hidden},
        "torch_version": torch.__version__,
        "output_allclose": True,
        "rows": rows,
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open("x") as stream:
        json.dump(result, stream, indent=2)
        stream.write("\n")


if __name__ == "__main__":
    main()

#include "chunk_prefill.hpp"
