 TORCH_CHECK(ks.numel()==1 && vs.numel()==1 && variant>=0 && variant<=2);
 auto o=at::empty_like(q);
 chunk_prefill_args_t a{};
 a.query=q.data_ptr();a.key=k.data_ptr();a.value=v.data_ptr();a.out=o.data_ptr();
 a.block_table=bt.data_ptr();a.cu_seqlens_q=cq.data_ptr();a.cu_seqlens_k=used.data_ptr();
 a.max_queries=q.size(0);a.max_keys=maxk;a.total_seqlen_q=q.size(0);
 a.total_seqlen_k=get_paged_kv_cache_effective_total_seqlen(k);
 a.k_scale=ks.data_ptr();a.v_scale=vs.data_ptr();a.sm_scale=0.0625f;
 a.batch_size=1;a.num_heads_q=24;a.num_heads_k=4;a.head_size=256;
 a.max_blocks_per_seq=bt.size(1);a.block_size=1664;a.is_varlen=true;a.is_paged=true;a.is_causal=true;
 a.q_stride_seq=q.stride(0);a.q_stride_heads=q.stride(1);
 a.o_stride_seq=o.stride(0);a.o_stride_heads=o.stride(1);
 a.k_stride_seq=k.stride(1);a.k_stride_heads=k.stride(2);
 a.v_stride_seq=v.stride(1);a.v_stride_heads=v.stride(2);
 a.page_stride_elements=get_paged_kv_cache_page_stride_elements(k);
 auto& queue=c10::xpu::getCurrentXPUStream().queue();
 if(variant==0)launch<256,32>(queue,a);
 else if(variant==1)launch<128,16>(queue,a);
 else launch<64,8>(queue,a);
 return o;
}
TORCH_LIBRARY(b70_tiles,m){m.def("forward(Tensor q, Tensor k, Tensor v, Tensor bt, Tensor cq, Tensor used, Tensor ks, Tensor vs, int maxk, int variant) -> Tensor");}
TORCH_LIBRARY_IMPL(b70_tiles,XPU,m){m.impl("forward",&tiles);}

"""Chat defaults shared by browser and OpenAI-compatible coding clients."""

import json


def apply_defaults(data):
    if not isinstance(data, dict):
        return data
    if data.get("max_tokens") is None and data.get("max_completion_tokens") is None:
        data["max_tokens"] = 16384
    budget = data.get("thinking_token_budget")
    if budget is None or budget == -1:
        data["thinking_token_budget"] = 8192
    elif type(budget) is int and budget > 8192:
        data["thinking_token_budget"] = 8192
    data.setdefault("reasoning_effort", "medium")
    kwargs = data.get("chat_template_kwargs")
    if kwargs is None:
        kwargs = {}
        data["chat_template_kwargs"] = kwargs
    if isinstance(kwargs, dict):
        kwargs.setdefault("enable_thinking", data["reasoning_effort"] != "none")
        kwargs.setdefault("preserve_thinking", True)
    return data


class ChatDefaults:
    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if (
            scope["type"] != "http"
            or scope.get("method") != "POST"
            or scope.get("path") != "/v1/chat/completions"
        ):
            return await self.app(scope, receive, send)
        chunks = []
        while True:
            event = await receive()
            if event["type"] == "http.disconnect":
                return
            chunks.append(event.get("body", b""))
            if not event.get("more_body", False):
                break
        body = b"".join(chunks)
        try:
            data = json.loads(body)
            body = json.dumps(apply_defaults(data)).encode()
        except (ValueError, UnicodeError):
            pass  # The normal API validator reports malformed input.
        scope = dict(scope)
        scope["headers"] = [
            (key, value)
            for key, value in scope.get("headers", [])
            if key.lower() != b"content-length"
        ]
        scope["headers"].append((b"content-length", str(len(body)).encode()))
        delivered = False

        async def replay():
            nonlocal delivered
            if not delivered:
                delivered = True
                return {"type": "http.request", "body": body, "more_body": False}
            return await receive()

        await self.app(scope, replay, send)

#!/usr/bin/env python3
"""Verify sparse hybrid-cache prefix reuse, deterministic state and MTP use."""
from __future__ import annotations
import argparse
import json
from pathlib import Path
import time
import urllib.request
import uuid

METRICS = {
    "hits": ("vllm:prefix_cache_hits_total", "vllm:prefix_cache_hits"),
    "queries": ("vllm:prefix_cache_queries_total", "vllm:prefix_cache_queries"),
    "drafted": ("vllm:spec_decode_num_draft_tokens_total",),
    "accepted": ("vllm:spec_decode_num_accepted_tokens_total",),
    "preemptions": ("vllm:num_preemptions_total",),
}

def snapshot(root: str) -> dict[str,float]:
    text=urllib.request.urlopen(root+"/metrics",timeout=30).read().decode()
    result={}
    for logical,candidates in METRICS.items():
        for candidate in candidates:
            values=[float(line.split()[-1]) for line in text.splitlines()
                    if line.startswith(candidate+"{") or line.startswith(candidate+" ")]
            if values:
                result[logical]=sum(values); break
        else: raise RuntimeError(f"missing metric {logical}: {candidates}")
    return result

def request(root: str, model: str, messages: list[dict]) -> dict:
    before=snapshot(root)
    body={"model":model,"messages":messages,"max_tokens":32,"temperature":0.0,
          "stream":True,"stream_options":{"include_usage":True},
          "reasoning_effort":"none","thinking_token_budget":0,
          "chat_template_kwargs":{"enable_thinking":False,"preserve_thinking":True}}
    req=urllib.request.Request(root+"/v1/chat/completions",data=json.dumps(body).encode(),
                               headers={"Content-Type":"application/json"})
    started=time.monotonic(); first=None; parts=[]; usage={}
    with urllib.request.urlopen(req,timeout=3600) as response:
        for raw in response:
            line=raw.decode(errors="replace").strip()
            if not line.startswith("data:"): continue
            payload=line[5:].strip()
            if payload=="[DONE]": break
            event=json.loads(payload); usage=event.get("usage") or usage
            for choice in event.get("choices") or []:
                delta=choice.get("delta") or {}
                part=delta.get("content") or delta.get("reasoning") or delta.get("reasoning_content") or ""
                if part: first=first or time.monotonic(); parts.append(part)
    if first is None: raise RuntimeError("request produced no response token")
    after=snapshot(root)
    return {"ttft_s":first-started,"total_s":time.monotonic()-started,
            "usage":usage,"answer":"".join(parts).strip(),
            "metric_delta":{key:after[key]-before[key] for key in before}}

def main() -> int:
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root",default="http://127.0.0.1:18087")
    parser.add_argument("--model",default="Qwen3.8-27B")
    parser.add_argument("--records",type=int,default=800)
    parser.add_argument("--output",type=Path,required=True)
    args=parser.parse_args()
    markers={113:"ALPHA-731",args.records//2:"BETA-428",args.records-71:"GAMMA-905"}
    rows=[f"Record {i:04d}: subsystem datum {markers.get(i,f'ITEM-{i:04d}')}; retain this exact mapping."
          for i in range(args.records)]
    system=f"Run nonce {uuid.uuid4().hex}. Answer only from this document.\n"+"\n".join(rows)
    cases=[("Return only the code at record 0113.","ALPHA-731"),
           (f"Return only the code at record {args.records//2:04d}.","BETA-428"),
           (f"Return only the code at record {args.records-71:04d}.","GAMMA-905")]
    records=[]
    for question,expected in cases:
        row=request(args.root,args.model,[{"role":"system","content":system},
                                           {"role":"user","content":question}])
        row["expected"]=expected; row["correct"]=expected in row["answer"]
        if not row["correct"]: raise RuntimeError(f"state mismatch: {row}")
        records.append(row); print(json.dumps(row),flush=True)
    if records[0]["metric_delta"]["hits"] != 0: raise RuntimeError("cold request hit cache")
    for row in records[1:]:
        if row["metric_delta"]["hits"] <= 0: raise RuntimeError("warm request missed prefix cache")
        if row["metric_delta"]["drafted"] <= 0: raise RuntimeError("MTP was not exercised")
    if any(row["metric_delta"]["preemptions"] for row in records):
        raise RuntimeError("prefix/state check triggered a preemption")
    result={"status":"PASS","requests":records}
    args.output.write_text(json.dumps(result,indent=2)+"\n")
    return 0

if __name__=="__main__": raise SystemExit(main())

#!/usr/bin/env python3
"""Collect a value-free, attributable manifest from a running vLLM container."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import subprocess
import time


REPO = Path(__file__).resolve().parents[1]
WORKER_PATHS = (
    "/opt/venv/lib/python3.12/site-packages/vllm/v1/worker/xpu_worker.py",
    "/opt/venv/lib/python3.12/site-packages/vllm/v1/worker/gpu_worker.py",
    "/opt/venv/lib/python3.12/site-packages/vllm/v1/worker/gpu_model_runner.py",
    "/opt/venv/lib/python3.12/site-packages/vllm/v1/worker/xpu_model_runner.py",
    "/opt/venv/lib/python3.12/site-packages/b70_attention.py",
    "/opt/b70/tiles.so",
)


def output(command: list[str], *, check: bool = True) -> str:
    result = subprocess.run(command, check=check, text=True, capture_output=True)
    return result.stdout.strip()


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def container_probe(container: str) -> dict[str, object]:
    source = r'''import hashlib, importlib.metadata, json, platform, subprocess
from pathlib import Path
paths = json.loads(__import__("os").environ["B70_MANIFEST_PATHS"])
versions = {}
for name in ("vllm", "vllm-xpu-kernels", "torch", "triton", "pytorch-triton-xpu"):
    try: versions[name] = importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError: versions[name] = None
files = {}
for item in paths:
    path = Path(item)
    files[item] = hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None
driver_packages = {}
for name in ("intel-igc-core-2", "intel-igc-opencl-2", "intel-ocloc", "intel-opencl-icd", "libze-intel-gpu1", "libigdgmm12"):
    result = subprocess.run(["dpkg-query", "-W", "-f=${Version}", name], text=True, capture_output=True)
    driver_packages[name] = result.stdout if result.returncode == 0 else None
print(json.dumps({"packages": versions, "installed_files_sha256": files,
                  "driver_packages": driver_packages, "container_kernel": platform.release()}))'''
    return json.loads(
        output(
            [
                "docker",
                "exec",
                "-e",
                "B70_MANIFEST_PATHS=" + json.dumps(WORKER_PATHS),
                container,
                "python",
                "-c",
                source,
            ]
        )
    )


def git_identity() -> dict[str, object]:
    revision = output(["git", "-C", str(REPO), "rev-parse", "HEAD"])
    status = output(["git", "-C", str(REPO), "status", "--porcelain=v1"])
    diff = output(["git", "-C", str(REPO), "diff", "--binary", "HEAD"])
    untracked = []
    for line in status.splitlines():
        if line.startswith("?? "):
            path = REPO / line[3:]
            if path.is_file():
                untracked.append(
                    {"path": line[3:], "sha256": sha256(path.read_bytes())}
                )
    return {
        "revision": revision,
        "dirty": bool(status),
        "tracked_diff_sha256": sha256(diff.encode()),
        "untracked_files": untracked,
    }


def power_policy() -> dict[str, object]:
    caps = list(Path("/sys/bus/pci/devices/0000:03:00.0/hwmon").glob("*/power1_cap"))
    return {
        "pci_device": "0000:03:00.0",
        "power_cap_uw": int(caps[0].read_text()) if len(caps) == 1 else None,
        "power_cap_source_count": len(caps),
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--container", default="qwen38-vllm-production")
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()

    inspect = json.loads(output(["docker", "inspect", args.container]))[0]
    config = inspect["Config"]
    selected_env = {}
    for row in config.get("Env") or []:
        name, _, value = row.partition("=")
        if name.startswith(("B70_", "VLLM_", "ZE_", "PYTORCH_")) or name in {
            "HF_HUB_OFFLINE",
            "PYTHONPATH",
        }:
            selected_env[name] = value
    manifest = {
        "schema": 1,
        "captured_at_unix": time.time(),
        "control": "q128-mtp4-full-180w",
        "production_container": args.container,
        "container_image_reference": config["Image"],
        "container_image_id": inspect["Image"],
        "container_command": (config.get("Entrypoint") or []) + (config.get("Cmd") or []),
        "selected_environment": selected_env,
        "mount_destinations": sorted(item["Destination"] for item in inspect["Mounts"]),
        "runtime": container_probe(args.container),
        "repository": git_identity(),
        "power_policy": power_policy(),
        "model_identity": {
            "model": "mikeinnyc/Qwen3.8-27B-GPTQ-Int4-sym-G128-MTP-BF16",
            "revision": "a47b0c6f0d756bc394c4cc629d5b0ded1acc7001",
            "tokenizer_revision": "same pinned model revision",
            "high_precision_source_lineage": "unresolved; not inferred from the live config",
        },
        "quantization": {
            "target": "GPTQ symmetric INT4 group-size 128, W4A16 runtime",
            "draft": "BF16 MTP parameters with INT4 LM head and five INT4 linears",
            "draft_vocabulary": "full 248320-token vocabulary",
            "kv_cache": "FP8",
        },
        "storage_identity_audit": {
            "status": "pending in-process object inspection",
            "known": "packing code reads head.weight to create owned INT4 tensors",
            "not_claimed": "the wrapper alone does not prove source storage was released",
            "weight_values_recorded": False,
        },
        "rollback": "systemctl --user start qwen38.service",
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(manifest, indent=2) + "\n")
    print(args.output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Sample per-DRM-client VRAM accounting from inside the engine container."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import re
import time


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=Path("/evidence/memory-samples.jsonl"))
    parser.add_argument("--stop-file", type=Path, default=Path("/evidence/stop-memory-sampler"))
    parser.add_argument("--pci", default="0000:03:00.0")
    parser.add_argument("--interval", type=float, default=0.25)
    args = parser.parse_args()
    if not 0.05 <= args.interval <= 10:
        parser.error("--interval must be between 0.05 and 10 seconds")

    with args.output.open("x") as output:
        while not args.stop_file.exists():
            clients = {}
            for path in Path("/proc").glob("[0-9]*/fdinfo/*"):
                try:
                    text = path.read_text()
                except OSError:
                    continue
                if args.pci not in text:
                    continue
                fields = dict(re.findall(r"^(drm-[^:]+):\s*(.+)$", text, re.MULTILINE))
                client_id = fields.get("drm-client-id")
                if client_id:
                    clients[client_id] = {"pid": int(path.parts[2]), **fields}
            output.write(json.dumps({"time": time.time(), "clients": clients}) + "\n")
            output.flush()
            time.sleep(args.interval)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
